// BIMface相关接口：获取token和模型列表
import request from './request'

// 获取 Access Token
export const getToken = () => request.get('/bim/token')

// 获取模型 View Token
export const getViewToken = (fileId) => request.get(`/bim/view-token/${fileId}`)

// 获取模型列表（含viewToken）
export const getModels = () => request.get('/bim/models')
